  "steps": [
    {
      "id": 1,
      "claim": "Fluency in English requires the ability to produce and comprehend language spontaneously with appropriate lexical, grammatical, and pragmatic competence comparable to that of a native adult speaker in everyday conversation.",
      "evidence": "Standard linguistic definitions of fluency (e.g., CEFR C1/C2 criteria, academic literature on second‑language proficiency) emphasize integrated use of syntax, morphology, semantics, and pragmatics, not merely word‑level mimicry.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "All documented cases of talking birds (e.g., Alex the African Grey, other parrots) show word‑level learning and mimicry but lack evidence of the integrated grammatical and pragmatic competence required by the definition in step 1.",
      "evidence": "Research on Alex (Pepperberg 1999, 2010) demonstrates labeling and limited compositional use but no generative syntax or consistent pragmatic discourse; similar findings for other parrots.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "No peer‑reviewed study reports a bird that meets the fluency criteria outlined in step 1.",
      "evidence": "Comprehensive reviews of avian cognition and language (e.g., Pepperberg 2010; Shettleworth 2010) list no instances of birds achieving native‑like syntactic or pragmatic proficiency.",
      "weight": 0.25,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Therefore, the statement \"no birds have ever become fluent in English\" is true.",
      "evidence": "Logical conjunction of steps 1‑3: the required level of fluency is defined, birds do not meet it, and no evidence contradicts this.",
      "weight": 0.25,
      "depends_on": [1, 2, 3]
    }
  ],
  "answer": "C",
  "confidence": 0.94,
  "considered": [
    {
      "answer": "F",
